import { useState } from 'react';
import { useClientOptions, useCreateProject, type ProjectStatus } from './projects';

// Add-a-project form. useState holds only what the user is currently entering: the name, the chosen
// client id, and the lifecycle status to start the project in. On submit it POSTs
// {name, clientId, status} and invalidates the ['projects'] key. The client select's option values
// are client ids and the status select's values are the status codes (what the test selects by).
export function ProjectForm() {
  const [name, setName] = useState('');
  const [clientId, setClientId] = useState('');
  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
  const { data: clients } = useClientOptions();
  const create = useCreateProject();

  return (
    <form
      data-testid="project-form"
      onSubmit={(event) => {
        event.preventDefault();
        if (!name.trim() || !clientId) {
          return;
        }
        create.mutate(
          { name, clientId: Number(clientId), status },
          {
            onSuccess: () => {
              setName('');
              setClientId('');
              setStatus('ACTIVE');
            },
          },
        );
      }}
    >
      <input
        data-testid="project-form-name"
        placeholder="Name"
        value={name}
        onChange={(event) => setName(event.target.value)}
      />
      <select
        data-testid="project-form-client"
        value={clientId}
        onChange={(event) => setClientId(event.target.value)}
      >
        <option value="">Select a client</option>
        {(clients ?? []).map((client) => (
          <option key={client.id} value={client.id}>
            {client.name}
          </option>
        ))}
      </select>
      <select
        data-testid="project-form-status"
        value={status}
        onChange={(event) => setStatus(event.target.value as ProjectStatus)}
      >
        <option value="ACTIVE">Active</option>
        <option value="ON_HOLD">On hold</option>
        <option value="FINISHED">Finished</option>
      </select>
      <button data-testid="project-form-submit" type="submit">
        Add job
      </button>
    </form>
  );
}
import { Link } from '@tanstack/react-router';
import { ProjectRow } from '../../slots/defs/projectRow';
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { useSearchParam, asFlag, asString } from '../../url/useSearchParam';
import { useProjects } from './projects';

// The projects list. Reads server data straight from its query key and shows the client's NAME
// (served alongside each project), not the id. Archived projects are tucked away: they drop off the
// list unless the shared `showArchived` URL key (set by a toolbar control) reveals them.
export function ProjectList() {
  const { data: projects } = useProjects();
  const [showArchived] = useSearchParam('showArchived', asFlag);
  // Shared with the tag-filter toolbar control via the `projectTag` key (no import). When set, keep
  // only projects carrying that tag; empty shows every tag.
  const [tagFilter] = useSearchParam('projectTag', asString);
  // Shared with the status-filter toolbar control via the `projectStatus` key (no import). When set,
  // keep only projects at that lifecycle status; empty shows every status.
  const [statusFilter] = useSearchParam('projectStatus', asString);

  if (!projects) {
    return null;
  }

  if (projects.length === 0) {
    return <p data-testid="projects-empty">No jobs yet.</p>;
  }

  const tagId = tagFilter === '' ? undefined : Number(tagFilter);
  const shown = projects
    .filter((project) => showArchived || !project.archived)
    .filter((project) => tagId === undefined || project.tagIds.includes(tagId))
    .filter((project) => statusFilter === '' || project.status === statusFilter);

  return (
    <>
    <ProjectsToolbar.Slot />
    <table data-testid="projects-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Client</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {shown.map((project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
            <td data-testid="project-client">{project.clientName}</td>
            <td>
              <Link
                to="/projects/$projectId"
                params={{ projectId: String(project.id) }}
                data-testid={`project-open-${project.id}`}
              >
                Open
              </Link>
            </td>
            <td>
              <ProjectRow.Slot project={project} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
    </>
  );
}
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// The shape the server returns (a project joined to its client's name) and the query key everything
// that shows projects shares. Invalidating ['projects'] refreshes every view of projects.
// The lifecycle statuses a project can be marked with — shown on its row.
export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';

export type Project = {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
  tagIds: number[];
};

export const projectsKey = ['projects'] as const;

export function useProjects() {
  return useQuery({
    queryKey: projectsKey,
    queryFn: () => getJson<Project[]>('/api/projects'),
  });
}

export function useCreateProject() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { name: string; clientId: number; status: ProjectStatus }) =>
      postJson<Project>('/api/projects', input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: projectsKey }),
  });
}

// Delete a project the owner no longer needs: POSTs {id} and returns the id removed. Invalidates
// ['projects'] so every view of projects re-reads from the server and the row drops — the list is
// never hand-edited after the write (CLAUDE.md rule 5). The audit record is written server-side.
export function useDeleteProject() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => postJson<{ id: number }>('/api/projects/remove', { id }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: projectsKey }),
  });
}

// Archive a project instead of deleting it: POSTs {id} and returns the id archived. The project is
// kept server-side with its archived flag set; invalidating ['projects'] re-reads every view so the
// row drops off the lists with no hand-maintained list (CLAUDE.md rule 5). The audit record is
// written server-side.
export function useArchiveProject() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => postJson<{ id: number }>('/api/projects/archive', { id }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: projectsKey }),
  });
}

// The client choices the project form needs. Reads the SHARED ['clients'] key — no import of the
// clients feature; the two stay in step through the key, not a dependency.
type ClientOption = { id: number; name: string };

export function useClientOptions() {
  return useQuery({
    queryKey: ['clients'] as const,
    queryFn: () => getJson<ClientOption[]>('/api/clients'),
  });
}

