package net.officefloor.hq.app;

import java.util.regex.Pattern;
import org.springframework.web.bind.annotation.RequestBody;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.ObjectResponse;

/**
 * {@code POST /api/clients} — create a client from a {name, email} body and return the saved row
 * (with its generated id). Wired by {@code officefloor/rest/api/clients.POST.yml}. A client is never
 * saved without a proper email address: the email is validated here and rejected with 400 before it
 * reaches the repository (the DB CHECK in Flyway V2 is the matching last line of defence). An email
 * already in use by another client (active or archived) is likewise rejected with 400 before saving,
 * matching the UNIQUE constraint in Flyway V25 — two clients can never share an email.
 */
public class ClientsPostLogic {

    /** A proper email address: local part, @, and a domain with a dot — no whitespace. */
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    public void service(@RequestBody NewClient newClient, ClientRepository repository,
            ObjectResponse<Client> response) {
        String email = newClient.getEmail();
        if (email == null || !EMAIL.matcher(email.trim()).matches()) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A proper email address is required");
        }
        String normalised = email.trim();
        if (repository.existsByEmail(normalised)) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "That email is already in use");
        }
        Client saved = repository.save(new Client(newClient.getName(), normalised));
        response.send(saved);
    }

    /** Request body for creating a client. */
    public static class NewClient {
        private String name;
        private String email;

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        public String getEmail() {
            return email;
        }

        public void setEmail(String email) {
            this.email = email;
        }
    }
}
=== ClientForm ===
import { useState } from 'react';
import { isValidEmail } from './email';
import { useCreateClient } from './clients';

// Add-a-client form. useState holds only what the user is currently typing; on submit it validates
// the email, and only a proper address POSTs and invalidates the ['clients'] key. A blank or
// malformed email surfaces client-form-email-error and never creates a row. A well-formed email that
// is already in use is rejected by the server (ClientsPostLogic): the mutation errors and the same
// client-form-email-error is shown, so no duplicate row is added.
export function ClientForm() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [emailError, setEmailError] = useState<string | null>(null);
  const create = useCreateClient();

  return (
    <form
      data-testid="client-form"
      onSubmit={(event) => {
        event.preventDefault();
        if (!isValidEmail(email)) {
          setEmailError('Enter a valid email address.');
          return;
        }
        setEmailError(null);
        create.mutate(
          { name, email },
          {
            onSuccess: () => {
              setName('');
              setEmail('');
            },
            onError: () => setEmailError('That email is already in use.'),
          },
        );
      }}
    >
      <input
        data-testid="client-form-name"
        placeholder="Name"
        value={name}
        onChange={(event) => setName(event.target.value)}
      />
      <input
        data-testid="client-form-email"
        placeholder="Email"
        value={email}
        onChange={(event) => {
          setEmail(event.target.value);
          if (emailError) {
            setEmailError(null);
          }
        }}
      />
      {emailError && (
        <span data-testid="client-form-email-error" role="alert">
          {emailError}
        </span>
      )}
      <button data-testid="client-form-submit" type="submit">
        Add client
      </button>
    </form>
  );
}
=== clients.ts ===
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// The shape the server returns and the query key everything that shows clients shares. Two features
// stay in step by invalidating ['clients']; nothing imports a sibling to refresh it.
export type Client = { id: number; name: string; email: string; archived: boolean };

export const clientsKey = ['clients'] as const;

export function useClients() {
  return useQuery({
    queryKey: clientsKey,
    queryFn: () => getJson<Client[]>('/api/clients'),
  });
}

export function useCreateClient() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { name: string; email: string }) =>
      postJson<Client>('/api/clients', input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: clientsKey }),
  });
}

// Correct a client's name and email: POSTs {id, name, email} and returns the saved row. The server
// (ClientsUpdateLogic) holds the email to the same rules as creation and keeps the row's id;
// invalidating ['clients'] re-reads every view so the corrected name/email show with no
// hand-maintained list (CLAUDE.md rule 5). The correction is recorded to the audit file server-side.
export function useUpdateClient() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { id: number; name: string; email: string }) =>
      postJson<Client>('/api/clients/update', input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: clientsKey }),
  });
}

// Archive a client instead of deleting it: POSTs {id} and returns the id archived. The client is
// kept server-side with its archived flag set; invalidating ['clients'] re-reads every view so the
// row drops off the list and search with no hand-maintained list (CLAUDE.md rule 5). The audit
// record is written server-side.
export function useArchiveClient() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => postJson<{ id: number }>('/api/clients/archive', { id }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: clientsKey }),
  });
}

